import logging, sys, time, threading
from unittest import mock
import django
from django.conf import settings
from psycopg.pq import TransactionStatus

class FakeConn:
    """Stand-in for a psycopg connection: no server needed."""
    made = 0
    def __init__(self):
        type(self).made += 1
        self.pgconn = mock.MagicMock(); self.pgconn.transaction_status = TransactionStatus.IDLE
        self.info = mock.MagicMock(); self.info.parameter_status.return_value = "UTC"
        self._pool = None; self.closed = False; self.autocommit = True
    @classmethod
    def connect(cls, conninfo="", **kwargs):
        return cls()
    def cursor(self, *a, **k):
        return mock.MagicMock()
    def close(self):
        self.closed = True

popts = {"min_size": 1, "max_size": 2, "timeout": 3, "connection_class": FakeConn}
settings.configure(
    DATABASES={
        "plain": {"ENGINE": "django.db.backends.postgresql", "NAME": "db", "OPTIONS": {"pool": dict(popts)}},
        "role": {"ENGINE": "django.db.backends.postgresql", "NAME": "db",
                 "OPTIONS": {"pool": dict(popts), "assume_role": "app_role"}},
    },
    USE_TZ=True, TIME_ZONE="UTC",
)
django.setup()
logging.basicConfig(stream=sys.stdout, level=logging.WARNING, format="  [log %(name)s %(threadName)s] %(message)s")
from django.db import connections
for alias in ("plain", "role"):
    w = connections[alias]
    t0 = time.monotonic()
    try:
        conn = w.get_new_connection(w.get_connection_params())
        print("%s: got pooled connection after %.2fs: %s" % (alias, time.monotonic() - t0, type(conn).__name__))
        conn._pool.putconn(conn)
    except Exception as e:
        print("%s: FAILED after %.2fs: %s: %s" % (alias, time.monotonic() - t0, type(e).__name__, e))
    time.sleep(4 if alias == "role" else 0)
    w.close_pool()
EOF
