    return (rev, str(f.get("file","")).strip().lstrip("./"), str(f.get("line")), re.sub(r"\s+"," ",str(f.get("title",""))).strip().lower())
srcmap={}
for r in ["correctness","testing","reliability","adversarial","api-contract","maintainability"]:
    d=json.load(open(r+".json"))
